import {experienceMeta,experienceChannels} from './data/experience-meta.js';
import {priceCatalog} from './data/price-catalog.js';
import {providers} from './data/providers.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=id=>experienceChannels[id]?.name||priceCatalog.sources.find(s=>s.id===id)?.name||providers.find(p=>p.id===id)?.name||id;
export function experienceDetails(id){const m=experienceMeta[id];if(!m)return '';return `<section class="experience-record"><span class="eyebrow">经验档案 · 文档核对</span><h2>版本、适用范围与证据</h2><div class="evidence-grid"><div><b>文章版本</b><p>${esc(m.version)}</p></div><div><b>资料核对日期</b><p>${esc(m.reviewedAt)}</p></div><div><b>调用实测日期</b><p>${m.testedAt?esc(m.testedAt):'尚未实测'}</p></div><div><b>实际扣费</b><p>${m.cost===null?'未取得账单，不能记为 0 元':esc(m.cost+' '+m.currency)}</p></div></div><p>适用范围：${esc(m.scope)}</p><p class="mini-meta">${esc(m.changes)}</p><div class="tool-links">${m.models.map(x=>`<a class="tool-link" href="#model/${esc(x.id)}" data-route="model/${esc(x.id)}">${esc(x.name)}<small>${esc(x.version)}</small></a>`).join('')}</div><p>关联接入渠道：${m.channels.length?m.channels.map(id=>experienceChannels[id]?`<a href="${esc(experienceChannels[id].url)}" target="_blank" rel="noopener noreferrer">${esc(name(id))} ↗</a>`:`<button class="small-action" data-discover-provider="${esc(id)}">${esc(name(id))}</button>`).join(' · '):'以文内来源对应的官方接入为准'}</p><a href="#probes" data-route="probes">查看中转站实测档案 →</a></section>`;}
export function experienceFeedback(id){const m=experienceMeta[id];if(!m)return '';const channels=[...new Set([...m.channels,...priceCatalog.sources.map(s=>s.id)])];return `<section class="experience-record" id="experienceFeedback" data-article-id="${esc(id)}"><h2>纠错与复现反馈</h2><p id="feedbackCounts" role="status">正在读取本版本反馈…</p><p class="mini-meta">复现成功是用户自报，不等于本站实测。反馈按文章版本保存；具体内容进入核对队列，不直接公开。</p><form id="experienceForm"><div class="evidence-fields"><label>反馈类型<select name="kind"><option value="correction">纠错 / 补充</option><option value="reproduced">我已复现成功</option></select></label><label>实际使用的模型<select name="modelId">${m.models.map(x=>`<option value="${esc(x.id)}">${esc(x.version)}</option>`).join('')}</select></label><label>实际使用的渠道<select name="channelId">${channels.map(id=>`<option value="${esc(id)}">${esc(name(id))}</option>`).join('')}</select></label><label>适用任务 / 使用环境<input name="scope" required minlength="2" maxlength="500" placeholder="例如：中文客服，单轮短文本"></label><div id="reproducedFields" hidden><label>复现日期<input name="testedAt" type="date" max="${new Date(Date.now()+14*3600000).toISOString().slice(0,10)}"></label><label>实际费用（未知可留空）<input name="cost" type="number" min="0" step="any"></label><label>费用币种<select name="currency"><option>USD</option><option>CNY</option><option>CREDIT</option></select></label></div></div><label>详细说明<textarea name="note" required minlength="10" maxlength="2000" rows="4" placeholder="请写明错误位置、正确内容与依据，或复现步骤及结果。不要包含 API Key、客户资料或账单隐私。"></textarea></label><p class="mini-meta">点击提交会将这些字段保存到 VibeBase。使用匿名浏览器标识避免重复计数，不要求填写姓名或邮箱。</p><button class="soft-btn" type="submit">提交反馈</button><p id="feedbackStatus" role="status"></p></form></section>`;}
export function bindExperience(){const root=document.querySelector('#experienceFeedback');if(!root)return;const id=root.dataset.articleId,m=experienceMeta[id],form=root.querySelector('form'),status=root.querySelector('#feedbackStatus');
 async function counts(){try{const r=await fetch('/api/feedback?article='+encodeURIComponent(id));const data=await r.json();if(!r.ok)throw Error(data.error);if(root.isConnected)root.querySelector('#feedbackCounts').textContent=`本版本：${data.reproduced} 条用户复现反馈 · ${data.corrections} 条纠错 / 补充（均待核对）`;}catch{if(root.isConnected)root.querySelector('#feedbackCounts').textContent='反馈统计暂时无法读取，请稍后刷新。';}}
 form.elements.kind.onchange=()=>{const yes=form.elements.kind.value==='reproduced';root.querySelector('#reproducedFields').hidden=!yes;form.elements.testedAt.required=yes;form.elements.note.minLength=yes?2:10;};
 form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button[type="submit"]');button.disabled=true;status.textContent='正在保存…';try{const response=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(new FormData(form)),articleId:id,version:m.version})});const data=await response.json();if(!response.ok)throw Error(data.error||'提交失败');status.textContent=data.message;await counts();}catch(e){status.textContent=e.message+'；内容仍保留在表单中。';}finally{button.disabled=false;}};counts();
}
export function probesPage(){return `<div class="page"><div class="discovery-heading"><span class="eyebrow">CHANNEL EVIDENCE</span><h1>中转站实测档案</h1><p>采样环境、请求结果、首字延迟与扣费分别记录。公开目录可访问，不代表模型调用成功。</p></div><div class="notice">证据分三类：站方声明、公开目录采样、实际模型调用。只有实际调用样本才计算推理成功率与首字延迟；账单未取得时显示未知。</div><div class="price-controls"><label>渠道<select id="probeSource"><option value="all">全部 ${priceCatalog.sources.length} 家渠道</option>${priceCatalog.sources.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><button class="ghost-btn" id="refreshProbes">刷新档案</button></div><p id="probeStatus" role="status">正在读取采样记录…</p><div id="probeResults"></div><details class="notice"><summary>怎样理解这些结果</summary><p>成功率 = 有效完成的请求数 / 发起请求数。首字延迟只统计收到有效输出且完整成功的流式请求，并同时展示延迟样本数。P95 使用最近秩法；小样本不代表长期服务水平。</p><p>实际扣费必须来自对应测试的账单记录；Token × 公开单价属于估算，不能冒充账单。地区由采样者提供，未提供则标为未知。</p><p>当前不会在网页收集或代存你的 API Key。付费模型测试由站点运营者在受控环境配置预算后执行。</p></details></div>`;}
export function renderProbeRuns(runs,source='all'){
 const selected=priceCatalog.sources.filter(s=>source==='all'?runs.some(r=>r.sourceId===s.id):s.id===source);
 return (source==='all'?'<p class="mini-meta">'+(priceCatalog.sources.length-selected.length)+' 家渠道尚无记录，可用上方筛选查看。</p>':'')+selected.map(s=>{const records=runs.filter(r=>r.sourceId===s.id);return `<article class="experience-record"><div class="section-head"><h2>${esc(s.name)}</h2><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">站方公开目录 ↗</a></div><p class="mini-meta">站方声明：目录中的型号与价格由渠道提供，未据此认证底层模型身份。</p>${records.length?records.map(r=>{const inference=r.kind==='inference';return `<section class="probe-run"><span class="tag">${inference?'模型调用实测':'公开目录采样 · 非推理'}</span><p>${esc(r.startedAt)} 至 ${esc(r.endedAt)} · ${esc(r.region||'地区未提供')} · ${esc(r.environment||'环境未提供')}</p><p>模型版本：${esc(r.model||'不适用（未调用模型）')}</p><div class="evidence-grid"><div><b>${r.requests}</b><p>发起请求</p></div><div><b>${r.successes} / ${r.requests}</b><p>${inference?'推理有效完成':'目录获取成功'}</p></div><div><b>${r.requests?(r.successes/r.requests*100).toFixed(1)+'%':'—'}</b><p>仅本批样本成功率</p></div><div><b>${inference&&r.ttft?.p50!==null&&r.ttft?.p50!==undefined?esc(r.ttft.p50)+' ms':'—'}</b><p>首字延迟 P50</p></div></div><p>首字延迟 P95：${inference&&r.ttft?.p95!=null?esc(r.ttft.p95)+' ms':'未取得'} · 延迟有效样本：${inference?r.ttft?.samples||0:0}</p><p>实际扣费：${r.billing?.amount!=null?esc(r.billing.amount+' '+r.billing.currency)+'（'+esc(r.billing.evidence)+')':'未知 / 未取得对应账单'}${r.estimatedUsd!=null?'；按配置单价估算 $'+esc(r.estimatedUsd)+'，非实际扣费':''}</p><p>错误类型：${Object.keys(r.errors||{}).length?Object.entries(r.errors).map(([k,n])=>esc(k)+' × '+n).join('；'):'本批未记录错误'}</p>${!inference?'<p class="mini-meta">此记录仅验证目录访问；不能用于推断推理延迟、充值后可用性或底层模型身份。</p>':''}</section>`;}).join(''):'<p>尚无采样记录。请求数、成功率、首字延迟及实际扣费均未知。</p>'}</article>`;}).join('');
}
export function bindProbes(){const root=document.querySelector('#probeResults');if(!root)return;let runs=[];const source=document.querySelector('#probeSource'),status=document.querySelector('#probeStatus'),button=document.querySelector('#refreshProbes');const render=()=>{root.innerHTML=renderProbeRuns(runs,source.value);};source.onchange=render;button.onclick=async()=>{button.disabled=true;status.textContent='正在读取采样记录…';try{const response=await fetch('/api/probes'),data=await response.json();if(!response.ok)throw Error(data.error);if(!root.isConnected)return;runs=data.runs;status.textContent=`已发布 ${runs.length} 批记录，其中模型调用实测 ${runs.filter(r=>r.kind==='inference').length} 批。`;render();}catch(e){status.textContent=e.message;root.innerHTML='<p>无法读取档案，请重试。未将读取失败记为渠道测试失败。</p>';}finally{button.disabled=false;}};button.click();}
